/// <reference lib="webworker" />
/**
 * src/worker.js
 * -------------
 * High-performance Monte Carlo portfolio risk simulation Web Worker.
 *
 * Simulates 10,000 correlated 252-day paths for the ₹10,00,000 portfolio:
 *   Reliance (20%), HDFC Bank (20%), ICICI Bank (20%), TCS (15%), ITC (15%), L&T (10%)
 *
 * Models supported:
 *   - 'gaussian': Multivariate normal via Cholesky decomposition
 *   - 'student_t': Multivariate Student-t (df=4) with common daily chi-square shock
 *   - 'bootstrap': Historical resampling from 5-year empirical return matrix
 *
 * Metrics computed:
 *   - VaR 95, VaR 99 (₹ loss relative to initial value)
 *   - Expected Shortfall 95 (average ₹ loss in worst 5%)
 *   - Median final portfolio value
 *   - Probability of a 10%+ intra-year drawdown
 *   - Downsampled 64-point paths for 3D visualization
 *   - Tail mask (1 for worst 5% paths, 0 otherwise)
 */

// Mulberry32 fast deterministic seeded pseudo-random number generator
function createMulberry32(seed = 1) {
  let s = seed >>> 0;
  return function() {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function runSimulation(params, config = {}) {
  const model = config.model || 'gaussian';
  const stress = typeof config.stress === 'number' ? config.stress : 1.0;
  const useCrisis = Boolean(config.use_crisis);
  const numPaths = config.num_paths || 10000;
  const horizonDays = config.horizon_days || 252;
  const downsamplePoints = config.downsample_points || 64;
  const initialValue = params.meta?.initial_value || 1000000;
  const seed = typeof config.seed === 'number' ? config.seed : 1;
  const rand = createMulberry32(seed);

  const weights = params.meta.weights;
  const mu = params.mu;
  const chol = useCrisis ? params.crisis_chol : params.chol;
  const histReturns = params.hist_returns;
  const histT = params.hist_T;

  // 1. Precalculate portfolio mean return per day
  let mu_p = 0;
  for (let i = 0; i < 6; i++) {
    mu_p += weights[i] * mu[i];
  }

  // 2. Precompute vector c = w^T * L (length 6) for Cholesky projection
  //    Since portfolio shock = sum_i w_i (L * z)_i = sum_j (sum_{i>=j} w_i L_{i,j}) z_j
  const c = new Float64Array(6);
  for (let j = 0; j < 6; j++) {
    let sum = 0;
    for (let i = j; i < 6; i++) {
      sum += weights[i] * chol[i * 6 + j];
    }
    c[j] = sum;
  }

  // 3. For bootstrap: precompute daily historical portfolio returns & their mean
  let histPortReturns = null;
  let histMean_p = 0;
  if (model === 'bootstrap' && histReturns && histT) {
    histPortReturns = new Float64Array(histT);
    for (let t = 0; t < histT; t++) {
      let r_p = 0;
      for (let i = 0; i < 6; i++) {
        r_p += weights[i] * histReturns[t * 6 + i];
      }
      histPortReturns[t] = r_p;
      histMean_p += r_p;
    }
    histMean_p /= histT;
  }

  // Allocate result buffers
  // paths: numPaths * downsamplePoints (Float32Array for WebGL attribute efficiency)
  const paths = new Float32Array(numPaths * downsamplePoints);
  const finals = new Float64Array(numPaths);
  const pathIndices = new Int32Array(numPaths);

  // Downsample step mapping: maps index k (0..downsamplePoints-1) to day d (0..horizonDays)
  const downsampleDays = new Int32Array(downsamplePoints);
  for (let k = 0; k < downsamplePoints; k++) {
    downsampleDays[k] = Math.round((k * horizonDays) / (downsamplePoints - 1));
  }

  let drawdownCount = 0;
  const z = new Float64Array(6);

  // Main simulation loop
  for (let path = 0; path < numPaths; path++) {
    pathIndices[path] = path;
    let value = initialValue;
    let peakValue = value;
    let maxDrawdown = 0;

    let downsampleIdx = 0;
    paths[path * downsamplePoints + 0] = value;
    downsampleIdx++;

    for (let day = 1; day <= horizonDays; day++) {
      let dayReturn = mu_p;

      if (model === 'bootstrap') {
        // Sample random historical day
        const randIdx = (rand() * histT) | 0;
        const histDev = histPortReturns[randIdx] - histMean_p;
        dayReturn = mu_p + stress * histDev;
      } else {
        // 6 standard normals
        for (let i = 0; i < 6; i += 2) {
          let u = 0, v = 0;
          while (u === 0) u = rand();
          while (v === 0) v = rand();
          const r = Math.sqrt(-2.0 * Math.log(u));
          const th = 2.0 * Math.PI * v;
          z[i] = r * Math.cos(th);
          z[i + 1] = r * Math.sin(th);
        }

        let shock = 0;
        for (let j = 0; j < 6; j++) {
          shock += c[j] * z[j];
        }

        if (model === 'student_t') {
          // Degrees of freedom = 4
          // Sample common daily chi-square shock W ~ chi2(4) = -2 * ln(U1 * U2)
          let u1 = 0, u2 = 0;
          while (u1 === 0) u1 = rand();
          while (u2 === 0) u2 = rand();
          const chi2 = -2.0 * Math.log(u1 * u2);
          // Normalize variance by sqrt((df-2)/df) = sqrt(2/4) = 1/sqrt(2)
          // shock_t = shock * sqrt((df-2) / chi2) = shock * sqrt(2 / chi2)
          const scale_t = Math.sqrt(2.0 / Math.max(chi2, 1e-8));
          shock *= scale_t;
        }

        dayReturn = mu_p + stress * shock;
      }

      // Update portfolio value with daily compounding
      value *= (1.0 + dayReturn);
      if (value < 0) value = 0;

      // Intra-year peak and drawdown tracking
      if (value > peakValue) {
        peakValue = value;
      } else {
        const dd = (peakValue - value) / peakValue;
        if (dd > maxDrawdown) maxDrawdown = dd;
      }

      // Record downsampled point
      if (downsampleIdx < downsamplePoints && day === downsampleDays[downsampleIdx]) {
        paths[path * downsamplePoints + downsampleIdx] = value;
        downsampleIdx++;
      }
    }

    finals[path] = value;
    if (maxDrawdown >= 0.10) {
      drawdownCount++;
    }
  }

  // Sort paths by terminal value to compute percentiles, VaR, and ES
  // We sort an index array so we know exactly which paths belong to the tail
  pathIndices.sort((a, b) => finals[a] - finals[b]);

  const sortedFinals = new Float64Array(numPaths);
  for (let i = 0; i < numPaths; i++) {
    sortedFinals[i] = finals[pathIndices[i]];
  }

  // 95% VaR index: worst 5% cutoff (500th worst out of 10,000)
  const idx95 = Math.floor(0.05 * numPaths);
  // 99% VaR index: worst 1% cutoff (100th worst out of 10,000)
  const idx99 = Math.floor(0.01 * numPaths);

  const val95 = sortedFinals[idx95];
  const val99 = sortedFinals[idx99];

  // VaR is the portfolio loss relative to initial value (negative number)
  const var95 = val95 - initialValue;
  const var99 = val99 - initialValue;

  // Expected Shortfall 95 (average loss among all paths in the worst 5%)
  let sumWorst5Pct = 0;
  for (let i = 0; i < idx95; i++) {
    sumWorst5Pct += sortedFinals[i];
  }
  const meanWorst5Pct = sumWorst5Pct / idx95;
  const es95 = meanWorst5Pct - initialValue;

  // Median
  const median = (sortedFinals[Math.floor(numPaths / 2)] + sortedFinals[Math.ceil(numPaths / 2)]) / 2;

  // Tail mask: 1 if path index is in worst 5%, else 0
  const tailMask = new Uint8Array(numPaths);
  for (let i = 0; i < idx95; i++) {
    tailMask[pathIndices[i]] = 1;
  }

  const drawdownProb10pct = drawdownCount / numPaths;

  return {
    stats: {
      var95: Math.round(var95),
      var99: Math.round(var99),
      es95: Math.round(es95),
      median: Math.round(median),
      mean: Math.round(sortedFinals.reduce((a, b) => a + b, 0) / numPaths),
      drawdown_prob_10pct: Number(drawdownProb10pct.toFixed(4)),
      pct5_final: Math.round(val95),
      pct95_final: Math.round(sortedFinals[Math.floor(0.95 * numPaths)]),
      worst: Math.round(sortedFinals[0]),
      best: Math.round(sortedFinals[numPaths - 1])
    },
    paths,
    finals,
    tailMask
  };
}

// Web Worker message listener
if (typeof self !== 'undefined' && typeof self.postMessage === 'function' && typeof window === 'undefined') {
  self.onmessage = function (event) {
    const { type, params, config } = event.data || {};
    if (type === 'run' && params) {
      try {
        const startTime = performance.now();
        const result = runSimulation(params, config);
        const durationMs = performance.now() - startTime;

        self.postMessage({
          type: 'result',
          stats: result.stats,
          durationMs,
          paths: result.paths,
          finals: result.finals,
          tailMask: result.tailMask
        }, [result.paths.buffer, result.finals.buffer, result.tailMask.buffer]);
      } catch (err) {
        self.postMessage({
          type: 'error',
          error: err.message || String(err)
        });
      }
    }
  };
}
